import pathlib,json,sqlite3,hashlib,sys,xml.etree.ElementTree as E
P=pathlib.Path(__file__).parent;src=json.loads((P/'sources.json').read_text());by={a['number']:a for a in src};rows=[];pending=[]
entry="l'entrée en vigueur de la loi portant suppression des dispositions issues de la loi n° 2000-1208 du 13 décembre 2000"
def add(n,body,reason,notes,removed,full=True):
 a=by[n];r={k:a[k] for k in ('code_id','source_id','source_sha256','number')};r.update(proposed_xml=body,reason=reason,review_notes=notes,status='rewrite_draft')
 if full:r.update(change_type='full_repeal',repeal_policy_id='editorial_direction_2026_10_19',repeal_scope=removed)
 else:r.update(change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed)
 rows.append(r)
add('L453-1',f"""<p>Le présent article est abrogé à compter de {entry}.</p>
<p>I. — À compter de cette entrée en vigueur, les nouvelles acquisitions, les nouveaux emprunts et les nouveaux travaux d'un organisme d'habitations à loyer modéré ne sont plus subordonnés, directement ou indirectement, à une garantie de la Société de garantie des organismes d'habitations à loyer modéré contre les risques d'opérations immobilières sur le fondement du présent article. Aucune adhésion, nouvelle cotisation ou contribution ne peut être exigée sur ce seul fondement pour une opération nouvelle. À compter de cette entrée en vigueur, aucun nouveau fait générateur de cotisation ou de contribution ne peut naître sur le fondement du présent article ou de ses dispositions réglementaires d'application, y compris des anciens articles D. 453-1 à D. 453-8 et de leur annexe. La seule poursuite de la surveillance ou du règlement d'un risque antérieurement garanti ne crée pas une nouvelle obligation de cotiser ; seules demeurent exigibles sur ces fondements les créances légalement nées avant cette entrée en vigueur, même si leur échéance ou leur encaissement intervient après.</p>
<p>Les conventions de garantie valablement conclues et la couverture des opérations valablement garanties avant cette entrée en vigueur conservent leurs effets, y compris pour une perte ou une mise en jeu de la garantie postérieure. La suppression de l'obligation pour les opérations nouvelles ne peut être opposée à un bénéficiaire pour lui retirer une couverture déjà acquise, exiger une garantie de remplacement ou lui imposer une régularisation nouvelle. Les créances de cotisations ou de contributions légalement nées avant cette entrée en vigueur restent dues dans leurs conditions antérieures ; aucune restitution générale ne résulte de l'abrogation.</p>
<p>Les règles antérieures nécessaires à l'exécution et au règlement de ces engagements, notamment les fractions et seuils de couverture, le suivi des seuls risques déjà garantis, les modalités de versement et les droits de recours, restent applicables à ces engagements jusqu'à leur extinction. Elles n'autorisent ni à imposer une nouvelle opération garantie ni à étendre d'office l'assiette des cotisations ou des renseignements à des opérations nouvelles.</p>
<p>II. — Le régime spécial d'objet, d'actionnariat, de gouvernance, d'approbation des statuts et d'accès aux documents prévu par le présent article cesse de s'appliquer aux activités et opérations nouvelles. La société conserve sa personnalité morale, ses actifs, ses dettes et ses engagements valablement constitués ; l'abrogation n'emporte ni dissolution automatique, ni transfert de ses actifs, ni extinction des droits de ses actionnaires, créanciers ou bénéficiaires. Les statuts existants demeurent valables et peuvent être modifiés dans les conditions du droit commun, sans nouvelle approbation imposée sur le seul fondement abrogé.</p>
<p>Les pouvoirs de contrôle et d'accès aux documents antérieurement attachés à la gestion des garanties déjà accordées ne subsistent que dans la mesure nécessaire à leur exécution et à la protection des droits acquis. Les autres activités éventuelles de la société restent soumises au droit commun, notamment aux agréments et règles prudentielles qui leur sont applicables sur un fondement distinct. La présente abrogation ne crée aucune garantie de l'État et ne supprime aucune garantie de construction ou de vente imposée par un autre texte.</p>""",
"Abrogation du régime spécial et de la garantie SGA obligatoire créés par SRU164 : liberté de nouvelles opérations sans adhésion ni contribution imposée sur ce fondement. Exécution protégée des garanties acquises et créances antérieures, sans dissolution ou transfert automatique de la société ni garantie publique nouvelle.",
"Article actuel entier, notes (néant) et absence de projet antérieur lus. Création intégrale prouvée par SRU164I ; l'exception des SCI d'accession progressive est postérieure mais ne constitue qu'une exclusion du régime supprimé, sans raison d'en rétablir l'assujettissement. I/II restent identifiés pour la transition. Les fractions50–80% et les anciens seuils ne sont pas recopiés comme obligation future ; ils continuent d'opérer pour les conventions déjà couvertes. Les créances légalement nées sont préservées et aucune nouvelle régularisation de fin de régime n'est créée. L'extinction de la mission légale ne dissout pas la personne morale privée. Règlements D453-1à8 et annexe, R261-24-1 et L423-16 coordonnés dans le même ensemble ; D453-7 reste documentairement incomplet faute de formule JO. Les droits propres aux contrats et aides d'autres fondements sont distincts. Aucun budget de liquidation ou de garantie de l'État inventé.",
"Obligation SRU164 de garantie SGA avant acquisition, emprunt ou travaux d'accession et régime légal spécial de société, cotisations, contrôle et documents pour toutes nouvelles opérations.")
add('L453-3',f"""<p>Le présent article est abrogé à compter de {entry}.</p>
<p>L'obligation spéciale imposée aux organismes d'habitations à loyer modéré par le présent article cesse pour les contrats de vente en l'état futur d'achèvement conclus à compter de cette entrée en vigueur. Cette suppression ne dispense pas d'une garantie financière d'achèvement ou de remboursement lorsqu'elle est exigée par les articles L. 261-10, L. 261-10-1 et L. 261-11 ou par un autre fondement distinct.</p>
<p>Les contrats conclus antérieurement et les garanties valablement acquises conservent leurs effets jusqu'à leur terme. Les droits des acquéreurs et bénéficiaires, y compris leur droit de mettre en jeu une garantie pour une défaillance postérieure, ne sont ni réduits ni soumis à une nouvelle régularisation par la présente abrogation.</p>""",
"Suppression de l'obligation spéciale de garantie VEFA HLM créée par SRU164, sans supprimer les garanties générales de vente, notamment issues de la réforme2013, ni les garanties contractées au profit des acquéreurs antérieurs.",
"L453-3 entier et ses deux notes de reports d'entrée en vigueur lus. Le renvoi source au d de L261-11 est conservé comme preuve, mais la proposition distingue son abrogation de L261-10-1 introduit ultérieurement. L261-10, L261-10-1 et L261-11 actuels ont été lus entiers : le régime général de garantie peut continuer à s'appliquer et aucune disparition de toute garantie VEFA n'est annoncée. R261-24-1, modalité spéciale de garantie SGA, est abrogé pour les nouveaux contrats dans le même ensemble. Les reports2002/2003 et la coquille dans la note source ne sont pas utilisés pour invalider les anciens contrats.",
"Obligation spéciale créée par SRU164 imposant une garantie d'achèvement ou de remboursement aux organismes HLM lors de toutes nouvelles ventes en l'état futur d'achèvement, sous réserve des garanties générales distinctes.")
a=by['L423-16'];body=a['source_xml'];root=E.fromstring('<r>'+body+'</r>');ps=[E.tostring(x,encoding='unicode').strip() for x in root if x.tag=='p'];assert len(ps)==3
ps[2]="<p>L'organisme d'habitations à loyer modéré prêteur informe la caisse mentionnée à l'article L. 452-1 s'il exerce une activité locative de la conclusion et des conditions du prêt à l'organisme d'habitations à loyer modéré bénéficiaire.</p>"
ps.append(f"<p>À compter de {entry}, le présent article n'impose plus d'information de la société de garantie mentionnée à l'ancien article L. 453-1 au seul titre de l'exercice d'une activité d'accession à la propriété. Cette suppression ne remet pas en cause les obligations d'information déjà nées ni les engagements valablement souscrits qui sont nécessaires à l'exécution d'une garantie antérieure, dans les limites prévues par les dispositions transitoires de l'article L. 453-1. Elle ne permet ni d'étendre ces obligations à une opération nouvelle ni d'imposer une régularisation nouvelle du fait de l'abrogation.</p>")
add('L423-16','\n'.join(ps),"Coordination de la suppression du régime SGA : retrait du destinataire SGA pour l'information sur les prêts des organismes exerçant l'accession. Le régime de prêts, les bénéficiaires, plafonds de rémunération, déclaration ministérielle et information CGLLS restent intégralement conservés.","Source entière et absence de proposition antérieure lues. Cet article postérieur àSRU ne fait pas l'objet d'une abrogation générale : seul le renvoi à la mission légale SGA supprimée est coordonné. Deux premiers paragraphes reproduits intégralement, y compris15jours,1,5point et la syntaxe source du premier alinéa (« et de prêts »), sans correction silencieuse du renvoi monétaire. La continuité CGLLS ne préjuge pas de sa revue allSRU séparée. Les engagements d'information d'un contrat de garantie antérieur restent possibles pour ses seuls risques, sans nouveau pouvoir de contrôle sur toute l'activité.",["Information systématique de la société SGA sur la conclusion et les conditions des prêts participatifs d'un organisme exerçant une activité d'accession, renvoi direct devenu sans objet pour les opérations nouvelles après abrogation de L453-1."],False)
add('R261-24-1',f"""<p>Le présent article est abrogé à compter de {entry}.</p>
<p>Pour les contrats de vente en l'état futur d'achèvement conclus à compter de cette entrée en vigueur, la détention de la garantie SGA ne vaut plus, sur le fondement du présent article, justification des garanties de remboursement ou d'achèvement. L'attestation SGA de moins de six mois et la reconnaissance particulière de sa teneur par l'acquéreur ne sont plus exigées sur ce fondement. Les garanties imposées par un texte distinct restent applicables selon leurs propres conditions.</p>
<p>Les contrats et garanties valablement conclus antérieurement, les attestations régulièrement annexées et les droits qui en découlent demeurent valables et opposables. L'abrogation n'impose ni de renouveler une attestation, ni de remplacer une garantie acquise, ni de modifier un contrat antérieur, et ne prive pas l'acquéreur d'une mise en jeu ultérieure de sa garantie.</p>""",
"Coordination réglementaire de l'abrogation de L453-1/L453-3 : fin, pour les nouveaux contrats, de la justification spéciale par garantie SGA et de son attestation semestrielle, avec pleine exécution des garanties acquises.",
"Deux alinéas source entiers et absence de notes/projet antérieur lus. La disposition constitue une application réglementaire du mécanisme SRU164 ; elle ne prouve pas que les garanties générales de vente ont toutes été créées par SRU. Les articles L261-10/10-1/11 restent distincts. La fin de la voie SGA peut laisser applicable une garantie financière générale ; il faut l'expliquer sans promettre un allègement automatique équivalent à la suppression de toute protection VEFA. Pas de régularisation d'anciens contrats ni nouvelle garantie imposée à leur titre.",
"Modalité réglementaire permettant de justifier les garanties VEFA HLM par la seule garantie SGA et imposant une attestation SGA de moins de six mois ainsi qu'une reconnaissance contractuelle pour les nouvelles ventes.")
scopes={
'D453-1':("Délimitation obligatoire des opérations immobilières soumises à la convention spéciale SGA pour les ventes à construire, neuves, après amélioration, parts de sociétés et locations-accessions, avec exclusions commerciales accessoires.","Le champ complet source inclut six paragraphes de liste, les sociétés civiles et les exclusions commerciales accessoires ; tous lus. L'abrogation retire le champ du régime obligatoire futur, sans transformer les opérations exclues en opérations garanties ni réduire le champ d'une ancienne convention."),
'D453-2':("Calcul réglementaire de l'encours prévisionnel imposé pour la garantie SGA, déductions80%/95%, règle des locations-accessions agréées et engagement proportionnel des sociétés civiles pour les nouvelles opérations.","Trois alinéas entiers lus : prix terrains et frais, prix de revient, ventes notariées et80%des réservations,95%en location-accession, exception du prêt D331-76-5-1 et prorata des parts civiles. Ces règles ne deviennent pas des exigences nouvelles ; les encours déjà contractuellement couverts continuent d'être appréciés selon les règles valables de leur garantie."),
'D453-3':("Exigence de fonds propres au moins égaux à20%de l'encours prévisionnel et appréciation des pertes de l'activité de vente sur cinq exercices dans les nouvelles conventions SGA obligatoires.","Trois paragraphes source et note intégrale lus. La note2003-537art2 fixait le calcul transitoire2003–2007 à partir de l'exercice clos31décembre2003 ; elle demeure historique pour les engagements anciens, sans rouvrir cette période. La suppression ne retranche pas un exercice du calcul d'une garantie déjà acquise."),
'D453-4':("Seuil réglementaire de déclenchement SGA d'au moins50%des fonds propres moyens sur cinq ans, majoration pour risques spécifiques et fraction de perte garantie obligatoires pour les nouvelles conventions.","Les I et II entiers et la note2003-537art2 sont lus. Les seuils, franchise et fractions d'une convention antérieure ne sont pas renégociés d'office ; leur exécution reste protégée. Le futur droit commun ne reçoit ni seuil inventé ni garantie publique de remplacement."),
'D453-5':("Encadrement spécial SGA du versement du concours et de son éventuel remboursement lorsque l'organisme retrouve des moyens financiers suffisants pour les nouvelles conventions.","Alinéa entier et absence de notes lus. Le remboursement éventuellement dû en vertu d'une ancienne convention reste exigible selon cette convention ; l'abrogation ne rend pas définitif un concours antérieurement remboursable et ne crée pas de dette de clôture supplémentaire."),
'D453-6':("Obligations réglementaires de contrôle des risques, recours aux experts, transmission périodique de documents et durcissement des engagements SGA sur l'activité nouvelle.","Deux alinéas entiers lus. Les moyens d'expertise et d'information nécessaires à une ancienne garantie subsistent pour ses risques couverts, avec leur confidentialité ; aucune communication n'est exigible à propos de nouvelles opérations non couvertes et aucun durcissement d'office ne leur est transposé."),
'D453-8':("Obligation de faire figurer les clauses types réglementaires annexées au chapitre dans les nouvelles conventions de garantie SGA.","Alinéa source entier lu, sans notes. L'annexe complète est photographiée dans sources.json et supprimée pour les nouvelles conventions par une proposition distincte. Les clauses déjà intégrées à un contrat conservent leurs effets ; aucune réécriture automatique du contrat ni nouvelle régularisation n'est exigée."),
"Annexe à l'article D453-8":("Ensemble des clauses types obligatoires SGA des titresIàIV : déclarations, fonds propres, suivi et rapports, contrôles, octroi et mise en jeu, seuils et durée, modifications et confidentialité pour les nouvelles conventions.","Annexe source entière lue et conservée intégralement dans sources.json : titresIàIV ; clauses1,2, actualisation nonnumérotée,4à11 ; déclaration annuelle, tableau au moins trimestriel, majoration cotisation au plus80%, décision refus sous2mois, franchise50%, moyenne5ans, révision annuelle, sortie du dernier lot et préavis1mois, confidentialité. Aucun résumé n'est substitué au texte source. La proposition abroge toute la norme future ; elle préserve les clauses acquises jusqu'à sortie du dernier lot garanti, les remboursements éventuels et la confidentialité sans ouvrir de nouveau pouvoir sur des opérations non garanties.")}
for n,(scope,notes) in scopes.items():
 body=f"<p>Le présent article est abrogé à compter de {entry}.</p>" if not n.startswith('Annexe') else f"<p>La présente annexe est abrogée à compter de {entry}.</p>"
 # Full-repeal validator expects its ordinary article prefix, even for an article-labelled annex.
 if n.startswith('Annexe'):body=f"<p>Le présent article est abrogé à compter de {entry}. Cette abrogation porte sur l'ensemble de l'annexe à l'article D. 453-8.</p>"
 body+="\n<p>Ses prescriptions ne sont plus imposées pour les nouvelles opérations et conventions de garantie sur le seul fondement du régime spécial prévu à l'ancien article L. 453-1.</p>"
 body+="\n<p>Les dispositions antérieures et les clauses qu'elles ont valablement fait entrer dans les conventions restent applicables dans la seule mesure nécessaire à l'exécution des garanties acquises avant cette entrée en vigueur et à la protection des droits des bénéficiaires, créanciers et tiers. Elles ne permettent ni d'assujettir une opération nouvelle à la garantie, ni d'étendre une couverture de plein droit, ni d'exiger une nouvelle cotisation ou une régularisation du seul fait de l'abrogation.</p>"
 body+="\n<p>La couverture des opérations déjà garanties demeure acquise jusqu'à son terme, y compris lorsque la perte, la demande de garantie ou le versement intervient après cette entrée en vigueur. Les créances légalement nées avant cette date restent dues et les obligations de confidentialité, de conservation des pièces et de remboursement valablement attachées aux engagements antérieurs restent applicables. Aucune restitution générale ni garantie de l'État n'est créée.</p>"
 add(n,body,'Suppression du dispositif réglementaire spécial SGA pour les nouvelles opérations, en conséquence de l’abrogation du régime créé par SRU164. '+scope,notes+' La filiation réglementaire2003/2007 puis reclassement2019 est relevée dans lineage.json ; il ne s’agit pas de déclarer toute norme postérieure automatiquement SRU. Les règles subsistent uniquement pour exécuter les engagements acquis, sans nouveau prélèvement ou assiette de contrôle.',scope)
# Remove only the precise SRU-created extension of mandatory promotion rules to HLM.
a=by['L222-2'];old=a['previous_draft']['proposed_xml'];parts=list(E.fromstring('<r>'+old+'</r>'));assert len(parts)==4
parts[0].text="L'application du premier alinéa de l'article L. 222-1 n'est pas non plus obligatoire, quel que soit le maître de l'ouvrage, lorsque la personne qui s'engage à faire construire est un organisme d'habitations à loyer modéré ou une société d'économie mixte dont plus de la moitié du capital appartient à des personnes morales de droit public."
body='\n'.join(E.tostring(p,encoding='unicode') for p in parts)
body+=f"\n<p>L'exemption applicable aux organismes d'habitations à loyer modéré vaut pour les contrats conclus à compter de {entry}. Elle n'éteint ni ne modifie les obligations des contrats antérieurs ni les garanties valablement constituées pour leur exécution. Les dispositions impératives fondées sur un autre texte restent applicables.</p>"
add('L222-2',body,"Suppression précise de l'extension SRU164III des règles obligatoires du contrat de promotion aux organismes HLM : exemption future expressément réécrite, autres exceptions et garantie autonome du vendeur conservées intégralement.","Texte actuel entier, notes (néant), proposition antérieure entière et version1978–2000 LEGIARTI000006824484 lus. SRU164III a seulement supprimé les mots « un organisme d'habitations à loyer modéré ou » : c'est une extension d'obligation encore actuelle, pas une création de tout l'article. Le candidat réintroduit expressément cette seule exemption après vérification, sans restauration automatique générale des règles antérieures. Les paragraphes2à4 de l'ancienne proposition sont préservés, y compris majorité publique stricte, opérations administratives seules, terrain conservé et garantie du vendeur. L222-1 et L222-3 lus pour portée ; aucune exemption aux garanties de vente L261-* n'en découle. Empreinte de l'ancien projet capturée avant rédaction ; archivage/intégration réservés au parent.",["Assujettissement nouveau des organismes HLM aux obligations du premier alinéa L222-1, produit par la suppression de leur exemption à SRU164III, pour les seuls contrats futurs."],False)
body=f"""<p>Lorsqu'ils agissent comme promoteurs dans le cadre d'un contrat de promotion immobilière ou de l'écrit prévu aux articles L. 212-10 et L. 213-6, les organismes d'habitations à loyer modéré et les sociétés d'économie mixte dont plus de la moitié du capital appartient à des personnes de droit public sont dispensés de fournir la garantie prévue au h de l'article L. 222-3.</p>
<p>La dispense applicable aux organismes d'habitations à loyer modéré vaut pour les contrats conclus à compter de {entry}. Elle n'éteint ni ne modifie les garanties valablement constituées pour les contrats antérieurs et ne prive pas leur bénéficiaire d'une mise en jeu ultérieure. Les autres garanties imposées par un fondement distinct ne sont pas supprimées.</p>"""
add('L222-6',body,"Suppression ciblée de la charge créée par SRU164IV : dispense HLM de la garantie propre au contrat de promotion pour les contrats futurs. Le régime SEM et les garanties déjà promises demeurent.","Source entière, notes (néant), proposition antérieure entière et version1978–2000 LEGIARTI000006824490 lus. SRU164IV a retiré les organismes HLM de la dispense, en maintenant les SEM majoritairement publiques. L222-3h lu : la garantie vise la bonne exécution de la mission du promoteur, pas toutes les assurances ou garanties de vente. La nouvelle règle écrit explicitement une exemption bornée après vérification de filiation ; aucune restauration tacite ni annulation de contrat ancien. Les deux supports contractuels et la condition de capital public SEM restent identiques. Les anciennes propositions et empreintes figurent dans sources.json.",["Obligation de fournir la garantie du h de L222-3 ajoutée aux organismes HLM par la suppression de leur dispense à SRU164IV, pour les seuls nouveaux contrats de promotion."],False)
# D453-7: keep genuinely missing source visible; do not put it into the complete set.
a=by['D453-7'];pending.append({'number':a['number'],'code_id':a['code_id'],'source_id':a['source_id'],'source_sha256':a['source_sha256'],'source_xml':a['source_xml'],'source_notes_xml':a['source_notes_xml'],'documentary_recovery_complete':False,'normative_complete':False,'count_as_completed':False,'missing':'Formule graphique de calcul de l’engagement total de la SGA, placée après « L’engagement total de la société est calculé selon la formule suivante » ; le XML ne contient qu’un renvoi au JO.','official_url':'https://www.legifrance.gouv.fr/jo_pdf.do?id=JORFTEXT000017767416','official_jorf_reference':'JORF n°303 du30décembre2007, texte157','attempts':[{'url':'https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000017767416','tool':'web.open','result':'inaccessible'},{'url':'https://www.legifrance.gouv.fr/jo_pdf.do?id=JORFTEXT000017767416','tool':'web.open','result':'inaccessible'}],'prior_download_evidence':'legal-rewrite/attachments/complements-logement/download-evidence.json','decision_pending_source':'Supprimer régime futur et conserver strictement garanties anciennes ; ne pas deviner la formule ou prétendre la vérification complète.','coordination_required_before_claiming_complete':True})
pending[0]['proposed_xml_for_review_only']=f"""<p>Le présent article est abrogé à compter de {entry}.</p>
<p>Le régime spécial de plafonnement de l'engagement SGA et de surveillance de sa mission légale n'est plus imposé pour les opérations nouvelles sur le fondement du présent article.</p>
<p>Les dispositions antérieures nécessaires à la gestion et au règlement des garanties valablement acquises avant cette entrée en vigueur restent applicables à ces seuls engagements jusqu'à leur extinction, sans retrait de couverture, garantie de remplacement, nouvelle cotisation ou régularisation imposée du seul fait de l'abrogation. Les créances légalement nées avant cette entrée en vigueur demeurent dues ; les droits des bénéficiaires, créanciers et tiers sont préservés.</p>
<p>Les pouvoirs du commissaire du Gouvernement subsistent uniquement dans la mesure nécessaire à l'exécution des engagements antérieurs. Les contrôles et règles prudentielles d'un fondement distinct restent applicables selon leurs propres conditions. Aucune garantie publique nouvelle ni transfert d'actifs n'est créé.</p>"""
pending[0]['proposal_is_countable']=False
pending[0]['proposal_reason']='Projet de suppression du régime réglementaire futur SGA, qui ne dispense pas de récupérer et vérifier la formule officielle applicable aux engagements anciens ; cette réserve interdit de compter le dossier comme complet.'
a=by['L423-15'];root=E.fromstring('<r>'+a['source_xml']+'</r>');ps=[E.tostring(x,encoding='unicode').strip() for x in root if x.tag=='p'];assert len(ps)==2
